create table if not exists job_items(id uuid primary key default gen_random_uuid(),job_id uuid not null references automation_jobs(id) on delete cascade,scene_id uuid references scenes(id) on delete cascade,item_key text not null,status text not null default 'queued',attempt int not null default 0,checkpoint jsonb not null default '{}',input jsonb not null default '{}',output jsonb not null default '{}',idempotency_key text unique,lease_until timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
